package vpn.proxy

import android.util.Log
import org.json.JSONObject
import java.util.Base64

/**
 * Thin wrapper around libxray (gomobile AAR).
 *
 * libXray API (generated by gomobile):
 *   libXray.LibXray.runXrayFromJSON(base64Request: String): String   — base64-encoded JSON response
 *   libXray.LibXray.stopXray(): String
 *   libXray.LibXray.getXrayState(): Boolean
 *
 * Start sequence: XrayProxy.start(configJson) → local SOCKS5 on 127.0.0.1:[socksPort] is available.
 * Stop sequence:  XrayProxy.stop().
 *
 * The proxy config is provided exclusively by the backend (POST /auth/register).
 * There is no hardcoded fallback — callers must supply a valid JSON config.
 */
object XrayProxy {

    // On some old Android builds (seen in the wild: Xiaomi "cactus"/Redmi 6A, Android 9,
    // 32-bit arm) the process gets killed with SIGSYS/SYS_SECCOMP the moment libXray's Go
    // runtime is first touched: "seccomp prevented call to disallowed arm system call".
    // Go's runtime has used async goroutine preemption (signal-based, involving a
    // membarrier-family syscall) since ~1.19-1.21, and that syscall isn't on the fixed
    // seccomp allowlist these old kernels ship with - unlike ENOSYS, a blocked-but-unknown
    // syscall is a hard kill, not a recoverable error, so this has to be prevented before
    // it happens rather than caught. GODEBUG=asyncpreemptoff=1 disables that mechanism
    // (a real perf/latency tradeoff for goroutine scheduling, not a correctness one - fine
    // for a local SOCKS5 proxy). Must be set before *any* call into libXray.LibXray.* -
    // this object's init block runs once, on first access, before every other member below,
    // which is every call site there is (XrayProxy is the sole libXray touchpoint).
    init {
        try {
            android.system.Os.setenv("GODEBUG", "asyncpreemptoff=1", true)
        } catch (e: Throwable) {
            Log.e("XrayProxy", "Failed to set GODEBUG before Go runtime init", e)
        }
    }

    private const val TAG = "XrayProxy"

    const val SOCKS_PORT = 17808
    val socksPort: Int = SOCKS_PORT
    val socksHost: String = "127.0.0.2"

    var lastError: String? = null
        private set

    var proxyLogger: ((String) -> Unit)? = null

    private fun logD(msg: String) {
        Log.d(TAG, msg)
        proxyLogger?.invoke("D/$TAG: $msg")
    }
    private fun logE(msg: String, t: Throwable? = null) {
        if (t != null) Log.e(TAG, msg, t) else Log.e(TAG, msg)
        proxyLogger?.invoke("E/$TAG: $msg" + (if (t != null) " - ${t.message}" else ""))
    }

    /**
     * Set by [start] / [stop]. Lets callers ask "is xray up?" without touching libXray, whose
     * first use loads a gomobile native library and boots a Go runtime — hundreds of
     * milliseconds that must never land on the main thread just to answer a status question.
     */
    @Volatile
    private var startRequested: Boolean = false

    /** True only if xray was actually started; never triggers the native load by itself. */
    fun isStartedLocally(): Boolean = startRequested

    fun isRunning(): Boolean = try {
        libXray.LibXray.getXrayState()
    } catch (e: Throwable) {
        logE("getXrayState failed", e)
        false
    }

    /**
     * Real liveness check: [isRunning] only reflects libxray's internal
     * "did I start" flag, which stays true even if the Go runtime wedged or
     * the SOCKS5 listener stopped accepting connections. This actually
     * connects to the local SOCKS5 port to verify something is listening.
     */
    fun isHealthy(timeoutMs: Int = 300): Boolean {
        if (!isRunning()) return false
        return try {
            java.net.Socket().use { socket ->
                socket.connect(java.net.InetSocketAddress(socksHost, socksPort), timeoutMs)
                true
            }
        } catch (e: Exception) {
            logE("Health check failed: local SOCKS5 port not accepting connections", e)
            false
        }
    }

    /** Last result of [isHealthy], refreshed by the watchdog. See [isHealthyCached]. */
    @Volatile
    private var lastHealthy: Boolean = false

    /**
     * Non-blocking answer for callers on the main thread.
     *
     * [isHealthy] opens a real socket, so calling it from a UI callback — which is what the
     * connection-state observer used to do — stalls the frame for up to [timeoutMs] every
     * time the connection state flickers. Those callers read this cached value instead, and
     * the watchdog keeps it fresh from its own thread.
     */
    fun isHealthyCached(): Boolean = startRequested && lastHealthy

    /** Runs the real check and stores the result. Must not be called from the main thread. */
    fun refreshHealth(timeoutMs: Int = 300): Boolean {
        val healthy = isHealthy(timeoutMs)
        lastHealthy = healthy
        return healthy
    }

    fun start(configJson: String): Boolean {
        if (isRunning()) {
            logD("Already running")
            startRequested = true
            return true
        }
        startRequested = true
        return try {
            val request = buildRunRequest(configJson)
            val responseBase64 = libXray.LibXray.runXrayFromJSON(request)
            val response = decodeResponse(responseBase64)
            if (response.isSuccess) {
                lastError = null
                logD("Started on $socksHost:$socksPort")
                true
            } else {
                lastError = response.error
                logE("Start failed: ${response.error}")
                false
            }
        } catch (e: Throwable) {
            lastError = "${e.javaClass.simpleName}: ${e.message}"
            logE("Start exception", e)
            false
        }
    }

    fun stop() {
        startRequested = false
        try {
            libXray.LibXray.stopXray()
            logD("Stopped")
        } catch (e: Throwable) {
            logE("Stop exception", e)
        }
    }

    // ---- private helpers ----

    private fun buildRunRequest(configJson: String): String {
        var finalConfigJson = configJson.replace("\"127.0.0.1\"", "\"127.0.0.2\"")
        // No logs at all: xray's own log lines carry server addresses and every destination it
        // dials. Whatever the config says, the runtime keeps quiet; a failed start still reports
        // its reason through the libXray response (lastError).
        try {
            val configObj = JSONObject(finalConfigJson)
            configObj.put("log", JSONObject().put("loglevel", "none").put("access", "none"))
            finalConfigJson = configObj.toString()
        } catch (e: Exception) {
            logE("Config is not valid JSON", e)
        }

        val requestJson = JSONObject().apply {
            put("datDir", "")          // no geo dat files needed for basic VLESS
            put("mphCachePath", "")
            put("configJSON", finalConfigJson)
        }.toString()
        return Base64.getEncoder().encodeToString(requestJson.toByteArray())
    }

    private data class LibResponse(val isSuccess: Boolean, val error: String?)

    private fun decodeResponse(base64: String): LibResponse {
        return try {
            val json = String(Base64.getDecoder().decode(base64))
            val obj = JSONObject(json)
            val error = if (obj.has("error")) obj.optString("error").takeIf { it.isNotEmpty() } else null
            LibResponse(isSuccess = error == null, error = error)
        } catch (e: Throwable) {
            LibResponse(isSuccess = false, error = "Response parse error: ${e.message}")
        }
    }
}
